package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.objects.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Tests FIRST; Java UNRUN. Metadata/resolver only, no current/pixels/World grant. */
class TestCdR13EndWorldMappings {
 @Test void actualSixArgumentCatalogueAddsOnlyCapsuleAndFourResultsRoots()throws Exception{for(var a:TestCdR13FutureAssets.retail().all()){var o=CdR13ObjectAssets.fromAssets(a);var r=CdR13ReusedObjectAssets.fromAssets(a,o);var b=CdR13BossAssets.bind(a);var c=CdR13CapsuleAssets.bind(a);var s=CdR13ResultsAssets.bind(a,c);var old=CdObjectMappings.fromAct3FutureAssets(a,o,r,b);var next=CdObjectMappings.fromAct3FutureAssets(a,o,r,b,c,s);assertEquals(27,count(old,"tables"));assertEquals(32,count(next,"tables"));assertEquals(8,count(next,"staticPieces"));for(int f=0;f<9;f++)assertNotNull(next.resolve(c.mappingAddress(),false,f));for(var root:s.mappingRoots())for(int f=0;f<5;f++)assertNotNull(next.resolve(root.address(),false,f));assertThrows(UnsupportedOperationException.class,()->old.resolve(c.mappingAddress(),false,0));assertThrows(UnsupportedOperationException.class,()->next.resolve(c.mappingAddress(),false,9));}}
 @Test void foreignCapsuleOrResultsCannotExtendAnEqualCatalogue()throws Exception{var f=TestCdR13FutureAssets.retail();var a=f.good();var o=CdR13ObjectAssets.fromAssets(a);var r=CdR13ReusedObjectAssets.fromAssets(a,o);var b=CdR13BossAssets.bind(a);var c=CdR13CapsuleAssets.bind(a);var foreign=CdR13CapsuleAssets.bind(f.bad());assertThrows(IllegalArgumentException.class,()->CdObjectMappings.fromAct3FutureAssets(a,o,r,b,foreign,CdR13ResultsAssets.bind(a,c)));assertThrows(IllegalArgumentException.class,()->CdObjectMappings.fromAct3FutureAssets(a,o,r,b,c,CdR13ResultsAssets.bind(f.bad(),foreign)));}
 @Test void everyRetainedOldBossRootStillResolvesByteExact()throws Exception{for(var a:TestCdR13FutureAssets.retail().all()){var o=CdR13ObjectAssets.fromAssets(a);var r=CdR13ReusedObjectAssets.fromAssets(a,o);var b=CdR13BossAssets.bind(a);var c=CdR13CapsuleAssets.bind(a);var old=CdObjectMappings.fromAct3FutureAssets(a,o,r,b);var next=CdObjectMappings.fromAct3FutureAssets(a,o,r,b,c,CdR13ResultsAssets.bind(a,c));for(var v:CdR13BossAssets.Visual.values())for(int f=0;f<v.frameCount();f++)assertEquals(old.resolve(b.range(v.mappingTable()).nativeAddress(),false,f),next.resolve(b.range(v.mappingTable()).nativeAddress(),false,f));}}
 @Test void nativeIndexedRootsAreAddedOnceAndNoDoubledOffsetAliasIsAdmitted()throws Exception{for(var a:TestCdR13FutureAssets.retail().all()){var o=CdR13ObjectAssets.fromAssets(a);var r=CdR13ReusedObjectAssets.fromAssets(a,o);var c=CdR13CapsuleAssets.bind(a);var s=CdR13ResultsAssets.bind(a,c);var maps=CdObjectMappings.fromAct3FutureAssets(a,o,r,CdR13BossAssets.bind(a),c,s);int base=a.identity().file()==com.openggf.game.soniccd.CdNativeFile.R13C?0x20DECE:0x20DEE6;for(int offset:new int[]{0,10,20,30})for(int frame=0;frame<5;frame++)assertNotNull(maps.resolve(base+offset,false,frame));for(int offset:new int[]{40,50,60})assertThrows(UnsupportedOperationException.class,()->maps.resolve(base+offset,false,0));}}
 private static int count(CdObjectMappings value,String name)throws Exception{var f=CdObjectMappings.class.getDeclaredField(name);f.setAccessible(true);return((Map<?,?>)f.get(value)).size();}
}
